html:
{% set letter_head = frappe.get_doc("Letter Head", "Quickfix Letter Head") %}
<style>
@page {
    size: A4;
    margin: 1cm;
}
.letter-head {
    text-align: center;
    margin-bottom: 5px;
}
.letter-head img {
    max-height: 80px;
    max-width: 200px;
    margin-bottom: 0;
}
.shop-name{
    text-align: center;
}
.print-summary {
    text-align: center;
    font-size: 13px;
    margin: 5px 0 15px 0;
    font-weight: bold;
}
h3 {
    margin-top: 12px;
    margin-bottom: 6px;
}
.final-amount {
    font-size: 24px;
    font-weight: bold;
    text-align: right;
    margin-top: 10px;
}
.letter-footer {
    text-align: center;
    margin-top: 35px;
    padding-top: 10px;
    font-size: 10px;
}
</style>

<div class="letter-head">
    {{ letter_head.content }}
</div>
<div class="shop-name">
    {{ get_shop_name() }}
</div>
<div class="print-summary">
    {{ doc.print_summary }}
</div>

{% if doc.priority == "Urgent" %}
<div>
    URGENT
</div>
{% endif %}

<div>
    <h3>Customer Details</h3>

    <table>
        <tr>
            <td><strong>Job Card</strong></td>
            <td>{{ doc.name }}</td>
        </tr>

        <tr>
            <td><strong>Customer Name</strong></td>
            <td>{{ doc.customer_name }}</td>
        </tr>

        <tr>
            <td><strong>Phone</strong></td>
            <td>{{ doc.customer_phone }}</td>
        </tr>

        <tr>
            <td><strong>Email</strong></td>
            <td>{{ doc.customer_email }}</td>
        </tr>
    </table>
</div>

<div>
    <h3>Device Details</h3>

    <table>

        <tr>
            <td><strong>Device Type</strong></td>
            <td>{{ doc.device_type }}</td>
        </tr>

        <tr>
            <td><strong>Brand</strong></td>
            <td>{{ doc.device_brand }}</td>
        </tr>

        <tr>
            <td><strong>Model</strong></td>
            <td>{{ doc.device_model }}</td>
        </tr>

        <tr>
            <td><strong>IMEI / Serial</strong></td>
            <td>{{ doc.imei_or_serial }}</td>
        </tr>

        <tr>
            <td><strong>Status</strong></td>
            <td>{{ doc.status }}</td>
        </tr>

        <tr>
            <td><strong>Priority</strong></td>
            <td>{{ doc.priority }}</td>
        </tr>

    </table>
</div>

    <h3>Parts Used</h3>
    <table class="parts-table">
    <thead>
        <tr>
            <th>Part</th>
            <th>Part Name</th>
            <th>Quantity</th>
            <th>Unit Price</th>
            <th>Total</th>
        </tr>
    </thead>
    <tbody>
        {% for row in doc.parts_used %}
        <tr>
            <td>{{ row.part }}</td>
            <td>{{ row.part_name }}</td>
            <td>{{ row.quantity }}</td>
            <td>
                {{row.unit_price}}
            </td>
            <td>
                {{row.total_price}}
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>

<table>
    <tr>
        <td>
            <strong>Parts Total</strong>
        </td>

        <td class="amount">
            {{doc.parts_total}}
        </td>
    </tr>
    <tr>
        <td>
            <strong>Labour Charge</strong>
        </td>
        <td class="amount">
            {{doc.labour_charge}}
        </td>
    </tr>
</table>


<div class="final-amount">
    <strong>
        Final Amount:
        {{ frappe.utils.fmt_money(doc.final_amount, currency="INR") }}
    </strong>
</div>

<div class="letter-footer">
    {{ letter_head.footer }}
</div>
